/* ============================================================
   STAR WARS: A GALAXY LIFE — canon node system
   Absolute BBY/ABY timeline, Canon-Lock vs Legend mode,
   global events, origins, worlds, named characters, and
   flagship "replace the master" arcs.

   Years use the same convention as the source material: BBY is
   negative, ABY is positive, 0 is the Battle of Yavin (0 BBY and
   0 ABY are the same instant), so currentYear = birthYear + age
   works with plain integer arithmetic.

   ai_expand nodes from the design doc are hand-authored here
   (fixed branches) rather than generated by a live model, since
   this is a static site with no backend to safely call an LLM.
   ============================================================ */

const CANON_MODES = {
  CANON_LOCK: {
    id: 'CANON_LOCK',
    label: 'Canon Lock',
    blurb: 'The big beats always happen the way the films and shows say. You can be present at Order 66 or the Battle of Yavin, but you cannot change who lives or dies.',
  },
  LEGEND: {
    id: 'LEGEND',
    label: 'Legend Mode',
    blurb: 'You can replace canon figures — train Anakin, become the Emperor\'s apprentice, save someone who was never meant to live. The timeline re-branches around you.',
  },
};

/* Absolute birth windows, keyed to this game's existing flavor eras. */
const ABS_ERA_WINDOWS = {
  'old-republic': { birth: [-60, -33], ends: -19 },
  'fall-of-jedi': { birth: [-32, -22], ends: -19 },
  'reign-of-empire': { birth: [-21, 0], ends: 4 },
  'new-republic-rise': { birth: [5, 9], ends: 34 },
  'new-republic': { birth: [10, 25], ends: 34 },
  'first-order-rise': { birth: [15, 30], ends: 35 },
  'new-jedi-order': { birth: [31, 34], ends: 60 },
};

function rollBirthYear(eraId) {
  const w = ABS_ERA_WINDOWS[eraId];
  return randInt(w.birth[0], w.birth[1]);
}

