function characterAgeAtYear(character, year) {
  if (character.birthYear === null) return 999;
  return year - character.birthYear;
}
function canRomanceCharacter(playerAge, playerCanonMode, character, currentYear) {
  if (playerAge < 18) return false;
  if (!character.verbs.date) return false;
  if (character.verbs.date === 'forbidden' && playerCanonMode === 'CANON_LOCK') return false;
  return characterAgeAtYear(character, currentYear) >= 18;
}
function canKillCharacter(character, canonMode, currentYear) {
  if (canonMode === 'LEGEND') return true;
  if (character.deathYear === null) return false;
  return character.deathYear <= currentYear;
}

